        "\"ages\": " ++ show([i | i in Ages]),
        "\"children\": " ++ show([child[i] | i in Ages]),
        "\"countries\": " ++ show([country[i] | i in Ages]),
        "\"stories\": " ++ show([story[i] | i in Ages])
    ]),
    "}"
];
