% Define the number of cows and sons
int: num_cows = 25;
int: num_sons = 5;

% Define the number of cows to be assigned to each son
array[1..num_sons] of int: num_cows_per_son = [7, 6, 5, 4, 3];

% Define the milk production of each cow
array[1..num_cows] of int: milk_production = [i | i in 1..num_cows];

% Define the decision variable: assignment of cows to sons
array[1..num_cows] of var 0..num_sons-1: cow_assignments;

% Constraint: each cow is assigned to exactly one son
constraint forall (c in 1..num_cows) (
    cow_assignments[c] != 0 <-> sum(s in 1..num_sons) (s-1 == cow_assignments[c]) == 1
);

% Constraint: the number of cows assigned to each son is as specified
constraint forall (s in 1..num_sons) (
    num_cows_per_son[s] == sum([c | c in 1..num_cows where cow_assignments[c] == s-1])
);

% Constraint: the total milk production is the same for each son
constraint forall (s1, s2 in 1..num_sons) (
    sum([milk_production[c] | c in 1..num_cows where cow_assignments[c] == s1-1]) ==
    sum([milk_production[c] | c in 1..num_cows where cow_assignments[c] == s2-1])
);

% Solve the problem
solve satisfy;

% Output the solution
output [
    "{",
    "\"cow_assignments\": [" ++ join(", ", [show(cow_assignments[c]) | c in 1..num_cows]) ++ "]",
    "}"
];
```

