% Problem data
int: num_people;
array[1..num_people] of set of int: compatible;

% Decision variables
array[1..num_people, 1..num_people] of var 0..1: transplants;

% Constraints
constraint forall(i in 1..num_people) (
    % A person can donate to at most one person
    sum([transplants[i, j] | j in compatible[i]]) <= 1
);

constraint forall(j in 1..num_people) (
    % A person can receive a kidney from at most one person
    sum([transplants[i, j] | i in 1..num_people]) <= 1
);

constraint forall(i in 1..num_people, j in 1..num_people) (
    % A person can only donate to someone they are compatible with
    transplants[i, j] = 0 \/ j in compatible[i]
);

% Objective: Maximize the number of transplants
var int: total_transplants = sum([transplants[i, j] | i in 1..num_people, j in 1..num_people]);
constraint total_transplants = sum([sum([transplants[i, j] | j in 1..num_people]) | i in 1..num_people]);

solve maximize total_transplants;

% Output the transplants as a list of lists
