        at_most(option) >= sum(i in 1..num_cars-(per_slots[option]-1)) (
            sum(j in 0..per_slots[option]-1) (X[i+j])
        )
);

% Solve
solve satisfy;

% Output
output [
    "\"sequence\": [" ++ join(", ", [show(sequence[i]) | i in 1..num_cars]) ++ "]"
];
