int: n_slots = 9;  % The amount of slots on a template
int: n_templates = 2;  % The amount of templates
int: n_var = 7;  % The amount of different variations
array[1..n_var] of int: demand = [250, 255, 260, 500, 500, 800, 1100];  % The demand per variation

