% Problem 005: Low Autocorrelation Binary Sequences

int: n;  % Length of the binary sequence

% Decision variables: binary sequence S
array[1..n] of var -1..1: S;

% Constraint: S[i] should be either -1 or 1
constraint forall(i in 1..n) (
    S[i] != 0
);

% Function to calculate the k-th autocorrelation Ck with non-periodic boundary conditions
% function var int: Ck_non_periodic(int: k) = sum(i in 1..n-k) (S[i] * S[i+k]);

% Function to calculate the k-th autocorrelation Ck with periodic boundary conditions
function var int: Ck_periodic(int: k) = sum(i in 1..n) (S[i] * S[(i+k-1) mod n + 1]);

% Objective: minimize the sum of the squares of the autocorrelations E
var int: E = sum(k in 1..n-1) (Ck_periodic(k)^2);

% Solve for the minimum energy E
solve minimize E;

% Output the binary sequence and the energy value
output [
    "{",
    join(",", [
        "\"sequence\": [" ++ join(",", [show(S[i]) | i in 1..n]) ++ "]",
        "\"E\": " ++ show(E)
    ]),
    "}"
];
```

