include "globals.mzn";

int: n_teams = 9;
int: n_days = 18;

set of int: TEAMS = 1..n_teams;
set of int: DAYS = 1..n_days;

% Decision variables
array[TEAMS,TEAMS] of var bool: plays; % Whether team i plays team j
array[TEAMS,DAYS] of var 0..2: where;   % 0: bye, 1: home, 2: away
array[TEAMS,DAYS] of var TEAMS: against; % Opponent of team i on day d

% Mirroring scheme
set of int: PAIRS = {1,2,3,4,5,6,7,8,10,11};
array[PAIRS] of int: mirror_scheme = [8,9,12,13,14,15,16,17,18,11];

% Constraints
constraint forall (i in TEAMS, j in TEAMS where i != j) (
    plays[i,j] = (exists(d in DAYS) (against[i,d] = j))
);

constraint forall (i in TEAMS, d in DAYS) (
    where[i,d] = if against[i,d] = i then 1 else if exists(j in TEAMS) (against[j,d] = i) then 2 else 0
);

constraint forall (i in TEAMS) (
    sum(d in DAYS) (where[i,d] = 1) = 8 /\
    sum(d in DAYS) (where[i,d] = 2) = 8 /\
    sum(d in DAYS) (where[i,d] = 0) = 2
);

constraint forall (d in DAYS, i in TEAMS) (
    if where[i,d] != 0 then 
        exists(j in TEAMS where j != i) (against[i,d] = j /\ where[j,d] = 3 - where[i,d]) 
    else 
        true
);

constraint forall (p in PAIRS) (
    let { int: d1 = p; int: d2 = mirror_scheme[p]; } in
    forall (i in TEAMS) (
        against[i,d1] = against[i,d2]
    )
);

% No Two Final Aways
constraint forall (i in TEAMS) (
    not(where[i, n_days] = 2 /\ where[i, n_days-1] = 2)
);

% Home/Away/Bye Pattern Constraints
constraint forall (i in TEAMS, d in 3..n_days) (
    not(where[i,d-2] = 2 /\ where[i,d-1] = 2 /\ where[i,d] = 2) /\
    not(where[i,d-2] = 1 /\ where[i,d-1] = 1 /\ where[i,d] = 1) /\
    not(where[i,d-2] = 0 \/ where[i,d-2] = 2 /\ where[i,d-1] = 0 \/ where[i,d-1] = 2 /\ where[i,d] = 0 \/ where[i,d] = 2) /\
