    not(against[i,d-2] = 7 /\ against[i,d-1] = 2 /\ against[i,d] = 7) /\
    not(against[i,d-2] = 7 /\ against[i,d-1] = 4 /\ against[i,d] = 2) /\
    not(against[i,d-2] = 7 /\ against[i,d-1] = 4 /\ against[i,d] = 7)
);

% Other Constraints
constraint against[4,11] = 2 /\ against[2,11] = 4;
constraint against[4,2] = 3;
constraint where[2,16] = 0;
constraint where[7,17] != 1;
constraint where[7,1] = 0;
constraint where[1,n_days] != 2 /\ where[2,n_days] != 2 /\ where[6,n_days] != 2 /\ where[7,n_days] != 2;
constraint where[1,1] != 2 /\ where[5,1] != 2 /\ where[3,1] != 2 /\ where[7,1] != 2;
constraint where[5,n_days] != 0 /\ where[6,n_days] != 0;
constraint where[4,1] != 0;

% Redundant constraint to help the solver
