    forall (i in TEAMS where where[i,d] = 1) (
        exists(j in TEAMS where i != j) (where[j,d] = 2 /\ against[j,d] = i)
    )
);

% Output
array[1..n_teams,1..n_teams] of int: config;
constraint forall (i in TEAMS, j in TEAMS) (
    config[i,j] = bool2int(plays[i,j])
);

output [
    "{",
    "\"config\": ", show2d(config), ",",
    "\"where\": ", show2d(where),
    "}"
];
