```minizinc
% Sports Tournament Scheduling

% Input data
int: n_teams = 8;  % Number of teams

% Derived data
int: n_weeks = n_teams - 1;  % Number of weeks
int: n_periods = n_teams div 2;  % Number of periods per week

% Decision variables
array[1..n_weeks, 1..n_periods, 1..2] of var 1..n_teams: schedule;

% Constraints
constraint forall (w in 1..n_weeks) (
  forall (t in 1..n_teams) (
    exists (p in 1..n_periods, s in 1..2) (schedule[w, p, s] = t)
  )
);

constraint forall (t in 1..n_teams, p in 1..n_periods) (
  count([schedule[w, p, s] | w in 1..n_weeks, s in 1..2], t) <= 2
);

constraint forall (t1 in 1..n_teams, t2 in t1+1..n_teams) (
  exists (w in 1..n_weeks, p in 1..n_periods, s in 1..2) (
    (schedule[w, p, s] = t1 /\ schedule[w, p, 3-s] = t2) \/
    (schedule[w, p, s] = t2 /\ schedule[w, p, 3-s] = t1)
  )
);

constraint forall (w in 1..n_weeks, p in 1..n_periods) (
  schedule[w, p, 1] != schedule[w, p, 2]
);

% Output
array[1..n_weeks, 1..n_periods] of var 1..n_teams: home = array2d(1..n_weeks, 1..n_periods, [schedule[w, p, 1] | w in 1..n_weeks, p in 1..n_periods]);
array[1..n_weeks, 1..n_periods] of var 1..n_teams: away = array2d(1..n_weeks, 1..n_periods, [schedule[w, p, 2] | w in 1..n_weeks, p in 1..n_periods]);

output [
  "{",
  join(",", [
    "\"home\": " ++ show2d(home),
    "\"away\": " ++ show2d(away)
  ]),
  "}"
];

function string: show2d(array[int, int] of var int: x) =
  "[" ++ join(",", [show([x[i, j] | j in index_set2of(x)]) | i in index_set1of(x)]) ++ "]";
```

