int: num_triples = {num_triples};

array[1..num_triples, 1..3] of var 1..n: triples;

constraint forall(t in 1..num_triples) (
    let {{ var set of int: t_set = {{ triples[t,1], triples[t,2], triples[t,3] }} }} in
