array[1..l] of var -1..1: b;

% Define the periodic autocorrelation function (PAF) for a given array X and shift s
function var int: PAF(array[int] of var int: X, int: s) =
  sum([X[i] * X[(i + s - 1) mod l + 1] | i in 1..l]);

