int: num_bales = 5;
int: num_combinations = 10;

set of int: Bales = 1..num_bales;
set of int: Combinations = 1..num_combinations;

array[Combinations] of int: weights = [80, 82, 83, 84, 85, 86, 87, 88, 90, 91];

array[Bales] of var int: bales;

constraint sum(b in Bales)(bales[b]) = sum(w in Combinations)(weights[w]) div 4;

constraint forall(p in Combinations) (
    exists(b1, b2 in Bales where b1 < b2)(
        bales[b1] + bales[b2] = weights[p]
    )
);

constraint increasing([bales[b] | b in Bales]);

constraint forall(b1, b2 in Bales where b1 < b2) (
    exists(p in Combinations)(
        bales[b1] + bales[b2] = weights[p]
    )
);

solve satisfy;

output [
    "{",
    "\"bales\": " ++ show([bales[b] | b in Bales]),
    "}"
];
```

