def generate_minizinc_model():
    model = """
    include "globals.mzn";

    int: max_weight = 40;
    int: num_weights = 4;

    array[1..num_weights] of var 1..max_weight: weights;
    constraint increasing(weights);

    constraint forall(w in 1..max_weight) (
        exists(a in -1..1, b in -1..1, c in -1..1, d in -1..1) (
            w = a*weights[1] + b*weights[2] + c*weights[3] + d*weights[4]
        )
    );

    constraint sum([weights[i] | i in 1..num_weights]) <= max_weight;

    solve satisfy;

    output [
        "{",
        "\"weights\": " ++ show(weights),
        "}"
    ];
    """
